// MEDIUM: structure from the decompile; tangent maths summarised. Spline component is this+0x218; spline-mesh segments are this+0x220 (array) with count at this+0x228.
if (SplinePoints.Num() == 0 || SplineComponent == nullptr)
{
    return;
}
SplineComponent->SetSplinePoints(SplinePoints, true);   // 0x1441505c0 (Points, 1, 1)
for (int32 i = 0; i < SplinePoints.Num(); ++i)
{
    // Arrive/leave tangents come from SplineTangents[i] and SplineTangents[i+1] when in range.
    // Each tangent is normalised (rsqrt with a 1e-8 floor; a zero-length tangent becomes the default vector),
    // then projected onto the segment direction using the neighbouring points.
    FVector Arrive = NormaliseTangent(SplineTangents, i);
    FVector Leave = NormaliseTangent(SplineTangents, i + 1);
    SplineComponent->SetTangentsAtSplinePoint(i, Arrive, Leave, true);   // 0x1441512d0 (i, arrive, leave, 1, 1)
}
for (int32 k = 0; k < SplineMeshCount; ++k)               // count +0x228
{
    USplineMeshComponent* Mesh = SplineMeshes[k];         // +0x220
    if (Mesh == nullptr)
    {
        continue;
    }
    if (k < SplinePoints.Num() - 1)
    {
        SetMeshSegmentActive(Mesh, false);                // 0x144121f60(mesh, 0)
        // sample start/end positions and tangents at points k+1 / k+2 of the spline (0x14413aad0, 0x144140c10, 0x1441402b0)
        Mesh->SetStartAndEnd(StartPos, StartTan, EndPos, EndTan, true);   // 0x144150b60
    }
    else
    {
        SetMeshSegmentActive(Mesh, true);                 // 0x144121f60(mesh, 1)
    }
}
